  name: 'Test: Escape Closes Overlays And Returns Focus',
  args: {
    showUser: false,
    showSearch: true,
    searchItems: searchItemsFixture,
    showLogin: false,
    showMenuButton: true
  },
  play: async ({
    canvasElement
  }) => {
    const canvas = within(canvasElement);
    const doc = canvasElement.ownerDocument;
    const searchButton = canvas.getByRole('button', {
      name: /søk/i
    });

    // Opening the search moves focus into the search field, so the screen
    // reader lands in the overlay instead of staying on the toggle button.
    await userEvent.click(searchButton);
    await waitFor(() => {
      expect(doc.activeElement).toBe(canvas.getByRole('searchbox', {
        name: /søk/i
      }));
    });

    // Escape closes the overlay and hands focus BACK to the button that
    // opened it - without this the browser drops focus to <body> and a
    // keyboard user loses their place.
    await userEvent.keyboard('{Escape}');
    await waitFor(() => {
      expect(searchButton).toHaveAttribute('aria-expanded', 'false');
      expect(doc.activeElement).toBe(searchButton);
    });

    // Native menu Escape/focus behaviour is covered with real keyboard input
    // in progressiveEnhancement.test.ts (storybook userEvent is synthetic).
  }
